-- Test-database equivalent of the MySQL V1 baseline schema.
-- It exists so H2 can verify the same logical Entity model using H2 types.
create table bookmarks (content_item_id bigint not null, created_at timestamp(6) with time zone, id bigint generated by default as identity, user_account_id bigint not null, primary key (id), constraint uk_bookmark_user_content unique (user_account_id, content_item_id));
create table categories (id bigint generated by default as identity, name varchar(120) not null, slug varchar(120) not null unique, primary key (id));
create table content_item_categories (category_id bigint not null, content_item_id bigint not null, primary key (category_id, content_item_id));
create table content_item_levels (content_item_id bigint not null, level_id bigint not null, primary key (content_item_id, level_id));
create table content_items (published boolean not null, id bigint generated by default as identity, reviewed_at timestamp(6) with time zone, slug varchar(120) not null unique, source_ref varchar(160), review_note varchar(1000), review_status enum ('APPROVED','PENDING','REJECTED'), type enum ('GRAMMAR','WORD') not null, primary key (id));
create table content_review_history (content_item_id bigint not null, id bigint generated by default as identity, reviewed_at timestamp(6) with time zone not null, reviewer_id bigint, note varchar(1000), previous_status enum ('APPROVED','PENDING','REJECTED'), status enum ('APPROVED','PENDING','REJECTED') not null, primary key (id));
create table content_sources (id bigint generated by default as identity, version varchar(80), source_ref varchar(160) not null unique, display_name varchar(200) not null, license_summary varchar(500), license_url varchar(500), usage_note varchar(1000), attribution varchar(2000), primary key (id));
create table curation_review_history (id bigint generated by default as identity, record_id bigint not null, reviewed_at timestamp(6) with time zone not null, reviewer_id bigint not null, note varchar(1000), previous_status enum ('APPROVED','PENDING','REJECTED'), record_type enum ('COMPARISON','CONFIRMATION','ENRICHMENT','RELATION') not null, status enum ('APPROVED','PENDING','REJECTED') not null, primary key (id));
create table email_verification_tokens (created_at timestamp(6) with time zone not null, expires_at timestamp(6) with time zone not null, id bigint generated by default as identity, used_at timestamp(6) with time zone, user_account_id bigint not null, token_hash varchar(64) not null unique, primary key (id));
create table examples (display_order integer not null, content_item_id bigint not null, id bigint generated by default as identity, meaning_id bigint, japanese_text varchar(1000) not null, reading varchar(1000), translation varchar(1000), search_key varchar(2500), audio_file_name varchar(255), primary key (id));
create table grammar_comparisons (published boolean not null, review_status tinyint not null check ((review_status between 0 and 2)), grammar_relation_id bigint not null unique, id bigint generated by default as identity, reviewed_at timestamp(6) with time zone, source_ref varchar(300) not null, common_confusion varchar(3000), key_difference varchar(3000), summary varchar(3000), usage_difference varchar(3000), primary key (id));
create table grammar_confirmation_attempts (answered_at timestamp(6) with time zone not null, id bigint generated by default as identity, learner_profile_id bigint not null, question_id bigint not null, result enum ('CORRECT','INCORRECT') not null, primary key (id));
create table grammar_confirmation_choices (correct_answer boolean not null, display_order integer not null, id bigint generated by default as identity, question_id bigint not null, choice_text varchar(1000) not null, primary key (id));
create table grammar_confirmation_questions (published boolean not null, review_status tinyint not null check ((review_status between 0 and 2)), grammar_id bigint not null, id bigint generated by default as identity, reviewed_at timestamp(6) with time zone, source_ref varchar(300) not null, context varchar(3000), explanation varchar(3000), prompt varchar(3000) not null, question_type enum ('CONTEXT_GAP','MEANING_MATCH','RELATION_CHOICE') not null, primary key (id));
create table grammar_enrichments (published boolean not null, review_status tinyint not null check ((review_status between 0 and 2)), grammar_id bigint not null unique, id bigint generated by default as identity, reviewed_at timestamp(6) with time zone, source_ref varchar(300) not null, common_mistake varchar(3000), formation_supplement varchar(3000), learner_note varchar(3000), nuance varchar(3000), usage_note varchar(3000), primary key (id));
create table grammar_relations (published boolean not null, review_status tinyint not null check ((review_status between 0 and 2)), id bigint generated by default as identity, left_grammar_id bigint not null, reviewed_at timestamp(6) with time zone, right_grammar_id bigint not null, source_ref varchar(300) not null, relation_type enum ('CONFUSABLE','CONTRAST','SIMILAR') not null, primary key (id), constraint uk_grammar_relation_pair_type unique (left_grammar_id, right_grammar_id, relation_type));
create table grammars (content_item_id bigint not null unique, id bigint generated by default as identity, pattern varchar(200) not null, pattern_search varchar(200), connection varchar(500), explanation varchar(2000) not null, search_text varchar(2500), primary key (id));
create table imported_source_records (content_item_id bigint, id bigint generated by default as identity, source_note_id bigint not null, level_code varchar(20), note_type varchar(120) not null, source_ref varchar(160) not null, tags varchar(1000) not null, field_names clob not null, field_values clob not null, primary key (id), constraint uk_imported_source_record unique (source_ref, note_type, source_note_id));
create table learner_preference_categories (category_id bigint not null, preference_id bigint not null, primary key (category_id, preference_id));
create table learner_preference_levels (level_id bigint not null, preference_id bigint not null, primary key (level_id, preference_id));
create table learner_profiles (daily_goal integer, experience integer not null, onboarding_completed boolean, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, last_studied_at timestamp(6) with time zone, onboarding_completed_at timestamp(6) with time zone, updated_at timestamp(6) with time zone not null, user_account_id bigint unique, pending_growth_stage_key varchar(40), presented_growth_stage_key varchar(40), character_key varchar(80) not null, display_name varchar(120) not null, learner_key varchar(120) not null unique, primary key (id));
create table learner_study_preferences (daily_new_grammar_limit integer, daily_new_word_limit integer, reminder_enabled boolean, reminder_time time(0), id bigint generated by default as identity, learner_profile_id bigint not null unique, primary key (id));
create table learning_progress (consecutive_correct int default 0 not null, lapse_count int default 0 not null, review_count integer not null, content_item_id bigint not null, id bigint generated by default as identity, last_studied_at timestamp(6) with time zone not null, learner_profile_id bigint not null, next_review_at timestamp(6) with time zone not null, last_result enum ('CORRECT','INCORRECT') not null, learning_state varchar(20) default 'LEARNING', primary key (id), constraint uk_learning_progress_learner_content unique (learner_profile_id, content_item_id));
create table learning_streaks (current_streak integer not null, last_activity_date date, longest_streak integer not null, id bigint generated by default as identity, learner_profile_id bigint not null unique, primary key (id));
create table levels (id bigint generated by default as identity, code varchar(40) not null, level_system varchar(40) not null, name varchar(120) not null, primary key (id));
create table meanings (sense_order integer not null, id bigint generated by default as identity, word_id bigint not null, language_tag varchar(10) not null, search_key varchar(500), text varchar(500) not null, primary key (id));
create table password_reset_tokens (created_at timestamp(6) with time zone not null, expires_at timestamp(6) with time zone not null, id bigint generated by default as identity, used_at timestamp(6) with time zone, user_account_id bigint not null, token_hash varchar(64) not null unique, primary key (id));
create table quiz_attempts (earned_experience integer not null, streak_eligible boolean, answered_at timestamp(6) with time zone not null, id bigint generated by default as identity, learner_profile_id bigint not null, question_source_record_id bigint not null, result enum ('CORRECT','INCORRECT') not null, primary key (id));
create table quiz_session_items (answered boolean not null, correct boolean, earned_experience integer not null, position integer not null, answered_at timestamp(6) with time zone, content_item_id bigint not null, id bigint generated by default as identity, session_id bigint not null, instruction varchar(300) not null, correct_answer varchar(2000) not null, submitted_answer varchar(2000), choices_json clob, explanation clob, prompt clob not null, question_type enum ('GRAMMAR_CONTEXT_CHOICE','GRAMMAR_MEANING_TO_PATTERN','GRAMMAR_PATTERN_TO_MEANING','WORD_JAPANESE_TO_MEANING','WORD_MEANING_TO_JAPANESE','WORD_READING_CHOICE','WORD_READING_INPUT') not null, primary key (id), constraint uk_quiz_session_position unique (session_id, position));
create table quiz_sessions (answered_count integer not null, correct_count integer not null, earned_experience integer not null, total_questions integer not null, completed_at timestamp(6) with time zone, id bigint generated by default as identity, learner_profile_id bigint not null, started_at timestamp(6) with time zone not null, public_id varchar(36) not null unique, session_key varchar(120) not null unique, mode enum ('QUICK') not null, state enum ('ACTIVE','COMPLETED') not null, primary key (id));
create table study_collection_items (content_item_id bigint not null, created_at timestamp(6) with time zone, id bigint generated by default as identity, study_collection_id bigint not null, primary key (id), constraint uk_study_collection_content unique (study_collection_id, content_item_id));
create table study_collections (created_at timestamp(6) with time zone not null, id bigint generated by default as identity, updated_at timestamp(6) with time zone not null, user_account_id bigint not null, name varchar(80) not null, primary key (id));
create table study_queue_entries (content_item_id bigint not null, created_at timestamp(6) with time zone, id bigint generated by default as identity, user_account_id bigint not null, primary key (id), constraint uk_study_queue_user_content unique (user_account_id, content_item_id));
create table study_records (content_item_id bigint not null, id bigint generated by default as identity, learner_profile_id bigint not null, studied_at timestamp(6) with time zone not null, session_key varchar(120), activity_type enum ('NEW','RETRAIN','REVIEW'), result enum ('CORRECT','INCORRECT') not null, primary key (id), constraint uk_study_session_content unique (learner_profile_id, session_key, content_item_id));
create table today_study_session_items (completed boolean not null, position integer not null, completed_at timestamp(6) with time zone, content_item_id bigint not null, id bigint generated by default as identity, session_id bigint not null, planned_activity_type enum ('NEW','RETRAIN','REVIEW') not null, result enum ('CORRECT','INCORRECT'), primary key (id), constraint uk_today_session_position unique (session_id, position), constraint uk_today_session_content unique (session_id, content_item_id));
create table today_study_sessions (planned_new_grammar_count integer not null, planned_new_word_count integer not null, planned_review_count integer not null, session_date date not null, completed_at timestamp(6) with time zone, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, learner_profile_id bigint not null, session_key varchar(120) not null unique, state enum ('ACTIVE','COMPLETED') not null, primary key (id), constraint uk_today_study_session_learner_date unique (learner_profile_id, session_date));
create table user_accounts (email_verified boolean, id bigint generated by default as identity, joined_at timestamp(6) with time zone not null, display_name varchar(80) not null, login_id varchar(80) not null unique, password_hash varchar(100) not null, email varchar(160) unique, role enum ('ADMIN','USER') not null, primary key (id));
create table weakness_review_session_items (completed boolean not null, position integer not null, completed_at timestamp(6) with time zone, content_item_id bigint not null, id bigint generated by default as identity, session_id bigint not null, primary key (id), constraint uk_weakness_session_position unique (session_id, position), constraint uk_weakness_session_content unique (session_id, content_item_id));
create table weakness_review_sessions (completed_at timestamp(6) with time zone, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, learner_profile_id bigint not null, session_key varchar(120) not null unique, state enum ('ACTIVE','COMPLETED') not null, primary key (id));
create table words (content_item_id bigint not null unique, id bigint generated by default as identity, expression varchar(120) not null, expression_search varchar(120), part_of_speech varchar(120), reading varchar(120) not null, reading_search varchar(120), pitch_accent varchar(500), primary key (id));
create index idx_content_published_type on content_items (published, type);
create index idx_curation_history_target on curation_review_history (record_type, record_id, reviewed_at);
create index idx_email_verification_user_created on email_verification_tokens (user_account_id, created_at);
create index idx_grammar_pattern_search on grammars (pattern_search);
create index idx_password_reset_user_created on password_reset_tokens (user_account_id, created_at);
create index idx_quiz_session_owner_state on quiz_sessions (learner_profile_id, state);
create index idx_word_expression_search on words (expression_search);
create index idx_word_reading_search on words (reading_search);
